            <section class="sheet-strip"><div><span>Program Perawatan</span><strong>{{ $program->title }}</strong></div><div><span>Periode</span><strong>{{ $document['monthName'] }} {{ $checklist->year }}</strong></div><div><span>Tanggal Input Checklist</span><strong>{{ $checklist->checked_at?->format('d M Y') ?: '-' }}</strong></div><div><span>Total Peralatan</span><strong>{{ $document['summary']['total'] }}</strong></div><div><span>Hasil</span><strong>OK {{ $document['summary']['ok'] }} / NOT OK {{ $document['summary']['not_ok'] }}</strong></div></section>
            <table class="sheet-table"><thead><tr><th>No.</th><th>Nama Peralatan</th><th>Tanggal Jadwal</th><th>Check Point</th><th>Kondisi</th><th>Keterangan</th></tr></thead><tbody>@foreach($checklist->entries->sortBy(fn ($entry) => $entry->equipment?->name) as $index => $entry)<tr><td>{{ $index + 1 }}</td><td>{{ $entry->equipment?->name ?: '-' }}<small>{{ $entry->equipment?->asset_tag ?: ($entry->equipment?->serial_number ?: '-') }}</small></td><td>{{ count($document['scheduledDates']->get($entry->equipment_id, [])) ? implode(', ', $document['scheduledDates']->get($entry->equipment_id)) : '-' }}</td><td>{{ $program->title }}</td><td>{{ $entry->result === 'ok' ? 'OK' : 'NOT OK' }}</td><td>{{ $entry->remarks ?: '-' }}</td></tr>@endforeach</tbody></table>
            @if($checklist->notes)<div class="note"><span>Catatan Dokumen</span><p>{{ $checklist->notes }}</p></div>@endif
